// String returns the canonical JSON. Implements fmt.Stringer.
func (f Frozen) String() string {
	return f.Canonical
}

// Pretty re-indents a JSON string with 2-space indentation.
// Returns the original string unchanged if it is not valid JSON.
// Use this to display raw API response bodies in a readable form.
// Example: body |> json.Pretty()
func Pretty(s string) string {
	v := jsontext.Value([]byte(s))
	err := v.Indent(jsontext.WithIndent("  "))
	if err != nil {
		return s
	}
	return string(v)
}

// TryPretty re-indents a JSON string or returns an error when the input is not valid JSON.
// Use when malformed input must be surfaced, not silently passed through.
// Example: pretty, err := json.TryPretty(body)
func TryPretty(s string) (string, error) {
	v := jsontext.Value([]byte(s))
	err := v.Indent(jsontext.WithIndent("  "))
	if err != nil {
		return "", err
	}
	return string(v), nil
}

