// buildTable constructs the field mapping for a struct type under
// this codec's config. Called once per Encode/Decode; the reflect
// overhead is O(numFields) and negligible vs the JSON parse itself.
//
// Key priority: explicit Rename > `as "..."` tag > naming policy > Go field name.
// Omit priority: explicit Omit > `as "-"` tag.
func (c Codec) buildTable(rt reflect.Type) codecTable {
	fields := []codecField{}
	keyToIndex := map[string]int{}
	for i := range rt.NumField() {
		field := rt.Field(i)
		if !field.IsExported() {
			continue
		}
		goName := field.Name
		if c.omits[goName] {
			continue
		}
		tag, _ := field.Tag.Lookup("json")
		if tag == "-" {
			continue
		}
		jsonKey := ""
		if renamed, ok := c.renames[goName]; ok {
			jsonKey = renamed
		} else if tag != "" {
			parts := kukistring.Split(tag, ",")
			jsonKey = parts[0]
		}
		if jsonKey == "" {
			jsonKey = applyNaming(goName, c.naming)
		}
		omitEmpty := c.omitEmpties[goName]
		if !omitEmpty && tag != "" {
			parts := kukistring.Split(tag, ",")
			for _, p := range parts {
				if p == "omitempty" {
					omitEmpty = true
				}
			}
		}
		fields = append(fields, codecField{jsonKey: jsonKey, index: i, omitEmpty: omitEmpty})
		keyToIndex[jsonKey] = i
	}
	return codecTable{fields: fields, keyToIndex: keyToIndex}
}

// applyNaming converts a single PascalCase field name per the strategy.
func applyNaming(name string, naming Naming) string {
	switch n := naming.(type) {
	case AsIs:
		_ = n
		return name
	case SnakeCase:
		_ = n
		return toDelimited(name, underscoreRune)
	case CamelCase:
		_ = n
		return toCamelCase(name)
	case KebabCase:
		_ = n
		return toDelimited(name, hyphenRune)
	default:
		panic("unreachable")
	}
}

// underscoreRune is the numeric rune value for '_'.
const underscoreRune = rune(95)

// hyphenRune is the numeric rune value for '-'.
const hyphenRune = rune(45)

// toDelimited converts PascalCase to snake_case or kebab-case.
// delim is the numeric rune value (95 for '_', 45 for '-').
func toDelimited(s string, delim rune) string {
	if s == "" {
		return s
	}
	runes := []rune(s)
	result := []rune{}
	for i, r := range runes {
		if unicode.IsUpper(r) {
			if i > 0 {
				prev := runes[i-1]
				if unicode.IsLower(prev) {
					result = append(result, delim)
				} else if i+1 < len(runes) && unicode.IsLower(runes[i+1]) && unicode.IsUpper(prev) {
					result = append(result, delim)
				}
			}
			result = append(result, unicode.ToLower(r))
		} else {
			result = append(result, r)
		}
	}
	return string(result)
}

// toCamelCase lowercases just the first rune: FirstName -> firstName.
func toCamelCase(s string) string {
	if s == "" {
		return s
	}
	runes := []rune(s)
	if unicode.IsUpper(runes[0]) {
		runes[0] = unicode.ToLower(runes[0])
	}
	return string(runes)
}

// isZero reports whether v is the zero value for its type.
func isZero(v reflect.Value) bool {
	kind := v.Kind()
	if kind == reflect.Bool {
		return !v.Bool()
	}
	if kind == reflect.Int || kind == reflect.Int8 || kind == reflect.Int16 || kind == reflect.Int32 || kind == reflect.Int64 {
		return v.Int() == 0
	}
	if kind == reflect.Uint || kind == reflect.Uint8 || kind == reflect.Uint16 || kind == reflect.Uint32 || kind == reflect.Uint64 {
		return v.Uint() == 0
	}
	if kind == reflect.Float32 || kind == reflect.Float64 {
		return v.Float() == 0.0
	}
	if kind == reflect.String {
		return v.String() == ""
	}
	if kind == reflect.Pointer || kind == reflect.Interface || kind == reflect.Slice || kind == reflect.Map || kind == reflect.Chan || kind == reflect.Func {
		return v.IsNil()
	}
	return false
}

// PathSegment addresses one step of a lookup path: an object key or
// an array position. Build them with KeyOf and IndexOf.
type PathSegment interface{ isPathSegment() }

type Key struct {
	Name string
}

func (Key) isPathSegment() {}

type Index struct {
	Position int
}

func (Index) isPathSegment() {}

// KeyOf constructs an object-key path segment.
// Example: json.KeyOf("person")
func KeyOf(name string) PathSegment {
	return Key{Name: name}
}

// IndexOf constructs an array-position path segment.
// Example: json.IndexOf(0)
func IndexOf(position int) PathSegment {
	return Index{Position: position}
}

// LookupResult makes the three read outcomes explicit: the value was
// found, the path simply does not exist, or the document/structure is
// invalid. Only Invalid carries an error — a Missing path is data
// shape, not failure.
type LookupResult interface{ isLookupResult() }

type Found struct {
	Value JSONValue
}

func (Found) isLookupResult() {}

type Missing struct{}

func (Missing) isLookupResult() {}

type Invalid struct {
	Error error
}

func (Invalid) isLookupResult() {}

// ErrPathNotFound is returned by the StringAt/… typed helpers when no
// value lives at the requested path. Check with errors.Is. Lookup
// surfaces the same condition as the Missing variant instead.
var ErrPathNotFound = kukierrors.New("json: path not found")

// ErrTypeMismatch is returned by the StringAt/… typed helpers when the
// value at the path is present but not the expected JSON kind.
var ErrTypeMismatch = kukierrors.New("json: value is not of the expected type")

// walkSegments walks a jsontext decoder down `segs`, returning the
// jsontext.Value at that path. Returns ErrPathNotFound (wrapped) when
// a segment is absent. The caller owns the returned Value (it is a
// Clone so it survives past subsequent decoder use).
func walkSegments(data []byte, segs []PathSegment) (jsontext.Value, error) {
	if len(segs) == 0 {
		v := jsontext.Value(data)
		if !v.IsValid() {
			return nil, kukierrors.New("invalid json")
		}
		return v.Clone(), nil
	}
	dec := jsontext.NewDecoder(bytes.NewReader(data))
	return walkSegmentsDec(dec, segs)
}

// walkSegmentsDec is the recursive core of walkSegments. It consumes
// exactly the value at `segs` from dec, skipping past everything else.
// The returned Value is a clone so it remains valid after the decoder
// moves on.
func walkSegmentsDec(dec *jsontext.Decoder, segs []PathSegment) (jsontext.Value, error) {
	if len(segs) == 0 {
		v, derr := dec.ReadValue()
		if derr != nil {
			return nil, derr
		}
		return v.Clone(), nil
	}
	head := segs[0]
	rest := segs[1:]
	if ix, _isOk := head.(Index); _isOk {
		return walkArrayIndex(dec, ix.Position, rest)
	}
	if k, _isOk := head.(Key); _isOk {
		return walkObjectKey(dec, k.Name, rest)
	}
	return nil, kukierrors.New("json: unreachable path segment kind")
}

// walkObjectKey scans an object for `key`, descending into `rest` on
// a match and skipping unmatched values. Returns ErrPathNotFound if
// the key is absent, ErrTypeMismatch if the current value is not an object.
func walkObjectKey(dec *jsontext.Decoder, key string, rest []PathSegment) (jsontext.Value, error) {
	tok, terr := dec.ReadToken()
	if terr != nil {
		return nil, terr
	}
	if tok.Kind() != jsontext.KindBeginObject {
		return nil, wrapTypeMismatch(fmt.Sprintf("object at key '%v'", key), tok.Kind())
	}
	for {
		nameTok, nerr := dec.ReadToken()
		if nerr != nil {
			return nil, nerr
		}
		if nameTok.Kind() == jsontext.KindEndObject {
			return nil, wrapNotFound(fmt.Sprintf("key '%v' not found", key))
		}
		if nameTok.Kind() != jsontext.KindString {
			return nil, fmt.Errorf("json: expected string key, got %v", nameTok.Kind())
		}
		name := nameTok.String()
		if name == key {
			return walkSegmentsDec(dec, rest)
		}
		if serr := dec.SkipValue(); serr != nil {
			return nil, serr
		}
	}
}

// walkArrayIndex scans an array for element `idx`, descending into
// `rest` on a match and skipping earlier elements. Returns
// ErrPathNotFound if the index is out of bounds, ErrTypeMismatch if
// the current value is not an array.
func walkArrayIndex(dec *jsontext.Decoder, idx int, rest []PathSegment) (jsontext.Value, error) {
	tok, terr := dec.ReadToken()
	if terr != nil {
		return nil, terr
	}
	if tok.Kind() != jsontext.KindBeginArray {
		return nil, wrapTypeMismatch(fmt.Sprintf("array at index %v", idx), tok.Kind())
	}
	i := 0
	for {
		kind := dec.PeekKind()
		if kind == jsontext.KindEndArray {
			_, _ = dec.ReadToken()
			return nil, wrapNotFound(fmt.Sprintf("array index %v out of bounds", idx))
		}
		if i == idx {
			return walkSegmentsDec(dec, rest)
		}
		if serr := dec.SkipValue(); serr != nil {
			return nil, serr
		}
		i += 1
	}
}

// wrapNotFound wraps any error so errors.Is(err, ErrPathNotFound) is true.
func wrapNotFound(msg string) error {
	return fmt.Errorf("%w: %s", ErrPathNotFound, msg)
}

// valueToJSONValue converts a jsontext.Value into the JSONValue sum.
// Reuses the existing decodeJSON machinery by unmarshaling into any.
func valueToJSONValue(v jsontext.Value) (JSONValue, error) {
	if !v.IsValid() {
		return Null{}, kukierrors.New("invalid json value")
	}
	raw := *new(any)
	err := jsonv2.Unmarshal(v, &raw)
	if err != nil {
		return nil, err
	}
	return decodeJSON(raw), nil
}

// Lookup returns the JSONValue at the given path as an explicit
// three-state result: Found carries the value, Missing means the path
// does not exist (data shape, not failure), and Invalid means the
// document could not be parsed or the structure did not match (e.g.
// indexing a non-array). String is the home input; use LookupBytes
// for a list of byte.
// Example:
//
//	switch json.Lookup(text, json.KeyOf("person"), json.KeyOf("name")) as r
//	    when Found
//	        print(r.Value)
//	    when Missing
//	        print("(absent)")
//	    when Invalid
//	        print("bad document: {r.Error}")
func Lookup(data string, segments ...PathSegment) LookupResult {
	return LookupBytes([]byte(data), segments...)
}

// LookupBytes is the list-of-byte-input variant of Lookup.
// Example: r := json.LookupBytes(raw, json.KeyOf("count"))
func LookupBytes(data []byte, segments ...PathSegment) LookupResult {
	v, err := walkSegments(data, segments)
	if err != nil {
		if errs.Is(err, ErrPathNotFound) {
			return Missing{}
		}
		return Invalid{Error: err}
	}
	if derr := validateFullDocument(data); derr != nil {
		return Invalid{Error: derr}
	}
	value, verr := valueToJSONValue(v)
	if verr != nil {
		return Invalid{Error: verr}
	}
	return Found{Value: value}
}

// validateFullDocument confirms data holds exactly one JSON value and
// nothing more. jsontext.NewDecoder reads one top-level value; a second
// read must return io.EOF (no trailing data). Returns the trailing-data
// error otherwise, or the first-value parse error if the document is
// malformed.
func validateFullDocument(data []byte) error {
	dec := jsontext.NewDecoder(bytes.NewReader(data))
	if _, err := dec.ReadValue(); err != nil {
		return err
	}
	if _, err := dec.ReadToken(); err != nil && !errs.Is(err, io.EOF) {
		return err
	}
	return nil
}

// StringAt returns the string at the given path. Returns
// ErrPathNotFound if the key is absent, ErrTypeMismatch if the value
// is not a JSON string. The whole document must be valid — trailing
// garbage after the top-level value is rejected. String is the home
// input; use StringAtBytes for a list of byte.
// Example: s := json.StringAt(text, json.KeyOf("person"), json.KeyOf("name")) onerr return
func StringAt(data string, segments ...PathSegment) (string, error) {
	return StringAtBytes([]byte(data), segments...)
}

// StringAtBytes is the list-of-byte-input variant of StringAt.
// Example: s := json.StringAtBytes(raw, json.KeyOf("person")) onerr return
func StringAtBytes(data []byte, segments ...PathSegment) (string, error) {
	v, err := walkSegments(data, segments)
	if err != nil {
		return "", err
	}
	if derr := validateFullDocument(data); derr != nil {
		return "", derr
	}
	if v.Kind() != jsontext.KindString {
		return "", wrapTypeMismatch("string", v.Kind())
	}
	raw := *new(any)
	uerr := jsonv2.Unmarshal(v, &raw)
	if uerr != nil {
		return "", uerr
	}
	if s, _isOk := raw.(string); _isOk {
		return s, nil
	}
	return "", wrapTypeMismatch("string", v.Kind())
}

// IntAt returns the int64 at the given path. Returns ErrPathNotFound
// if absent, ErrTypeMismatch if not a number or if the number has a
// fractional part. Accepts integer-valued floats (42.0) since JSON has
// one number kind; rejects genuinely fractional values (42.5) and
// out-of-range integers that overflow int64. The whole document must
// be valid — trailing garbage after the top-level value is rejected.
// String is the home input; use IntAtBytes for a list of byte.
// Example: n := json.IntAt(text, json.KeyOf("count")) onerr return
func IntAt(data string, segments ...PathSegment) (int64, error) {
	return IntAtBytes([]byte(data), segments...)
}

// IntAtBytes is the list-of-byte-input variant of IntAt.
// Example: n := json.IntAtBytes(raw, json.KeyOf("count")) onerr return
func IntAtBytes(data []byte, segments ...PathSegment) (int64, error) {
	v, err := walkSegments(data, segments)
	if err != nil {
		return 0, err
	}
	if derr := validateFullDocument(data); derr != nil {
		return 0, derr
	}
	if v.Kind() != jsontext.KindNumber {
		return 0, wrapTypeMismatch("number", v.Kind())
	}
	raw := string(v)
	n, perr := strconv.ParseInt(raw, 10, 64)
	if perr == nil {
		return n, nil
	}
	bf, _, berr := big.ParseFloat(raw, 10, 128, big.ToNearestEven)
	if berr != nil {
		return 0, outOfIntRange(raw)
	}
	if !bf.IsInt() {
		return 0, wrapTypeMismatch("integer", v.Kind())
	}
	n, acc := bf.Int64()
	if acc != big.Exact {
		return 0, outOfIntRange(raw)
	}
	return n, nil
}

// outOfIntRange reports an integer literal too large to return as an
// int64, typed as ErrTypeMismatch — the value is a number, just not one
// that can come back as an integer.
func outOfIntRange(raw string) error {
	return fmt.Errorf("%w: integer literal %s out of int64 range", ErrTypeMismatch, raw)
}

// FloatAt returns the float64 at the given path. Returns
// ErrPathNotFound if absent, ErrTypeMismatch if not a number. The whole
// document must be valid — trailing garbage after the top-level value
// is rejected. String is the home input; use FloatAtBytes for a list of
// byte.
// Example: f := json.FloatAt(text, json.KeyOf("ratio")) onerr return
func FloatAt(data string, segments ...PathSegment) (float64, error) {
	return FloatAtBytes([]byte(data), segments...)
}

// FloatAtBytes is the list-of-byte-input variant of FloatAt.
// Example: f := json.FloatAtBytes(raw, json.KeyOf("ratio")) onerr return
func FloatAtBytes(data []byte, segments ...PathSegment) (float64, error) {
	v, err := walkSegments(data, segments)
	if err != nil {
		return 0.0, err
	}
	if derr := validateFullDocument(data); derr != nil {
		return 0.0, derr
	}
	if v.Kind() != jsontext.KindNumber {
		return 0.0, wrapTypeMismatch("number", v.Kind())
	}
	return strconv.ParseFloat(string(v), 64)
}

// BoolAt returns the bool at the given path. Returns ErrPathNotFound
// if absent, ErrTypeMismatch if not a JSON boolean. The whole document
// must be valid — trailing garbage after the top-level value is
// rejected. String is the home input; use BoolAtBytes for a list of
// byte.
// Example: b := json.BoolAt(text, json.KeyOf("active")) onerr return
func BoolAt(data string, segments ...PathSegment) (bool, error) {
	return BoolAtBytes([]byte(data), segments...)
}

// BoolAtBytes is the list-of-byte-input variant of BoolAt.
// Example: b := json.BoolAtBytes(raw, json.KeyOf("active")) onerr return
func BoolAtBytes(data []byte, segments ...PathSegment) (bool, error) {
	v, err := walkSegments(data, segments)
	if err != nil {
		return false, err
	}
	if derr := validateFullDocument(data); derr != nil {
		return false, derr
	}
	if v.Kind() == jsontext.KindTrue {
		return true, nil
	}
	if v.Kind() == jsontext.KindFalse {
		return false, nil
	}
	return false, wrapTypeMismatch("bool", v.Kind())
}

// wrapTypeMismatch wraps any error so errors.Is(err, ErrTypeMismatch) is true.
func wrapTypeMismatch(want string, got jsontext.Kind) error {
	return fmt.Errorf("%w: wanted %s, got %s", ErrTypeMismatch, want, got)
}
